<?php use Namira\{StoreForms,StoreOrderSchema,StoreCart,Security};$form=StoreForms::forProduct($db,$product);$feedback=$_SESSION['commerce_feedback']['input']??[];unset($_SESSION['commerce_feedback']);$values=$feedback['custom']??[];$lineId=(int)($_GET['line']??0);if($lineId){$token=StoreCart::token($db,$user);$line=Namira\Db::query($db,'SELECT * FROM store_cart_lines WHERE id=? AND cart_token=?',[$lineId,$token])->fetch();if(!$line)throw new Namira\HttpError(404,'ردیف سبد پیدا نشد.');$values=Namira\Protocol::decode($line['payload'])['values']??[];} ?>
